// Token Launch Radar — Offline Interactive Dashboard (vanilla ES, zero network dependencies).
// Reads window.RADAR_DATA generated by main.ts from the sealed DefiLlama snapshot.

(function initRadarDashboard() {
  'use strict';

  const DATA = window.RADAR_DATA;
  if (!DATA || !Array.isArray(DATA.rows)) {
    document.getElementById('view-container').innerHTML =
      '<div class="empty-state">Missing data.js dataset. Run node main.ts first.</div>';
    return;
  }

  const state = {
    view: 'board', // 'board' | 'live' | 'calibration' | 'sandbox'
    tier: 'all', // 'all' | 'watchlist' | 'early'
    category: 'all',
    chain: 'all',
    risk: 'all',
    query: '',
    sortKey: 'rank',
    sortDir: 'asc',
    page: 1,
    pageSize: 18,
    selectedSlug: null,
    sandbox: {
      growth_weight: DATA.model.growth_weight,
      maturity_range: DATA.model.maturity_range,
      chain_bonus_per_extra: DATA.model.chain_bonus_per_extra,
      scale_exponent: DATA.model.scale_exponent,
    },
  };

  // --- Formatting helpers ---
  function fmtUsd(n) {
    if (n === null || n === undefined || !Number.isFinite(n)) return '—';
    const abs = Math.abs(n);
    if (abs >= 1e9) return '$' + (n / 1e9).toFixed(2) + 'B';
    if (abs >= 1e6) return '$' + (n / 1e6).toFixed(abs >= 1e8 ? 1 : 2) + 'M';
    if (abs >= 1e3) return '$' + (n / 1e3).toFixed(0) + 'K';
    return '$' + Math.round(n).toLocaleString('en-US');
  }

  function fmtPct(n) {
    if (n === null || n === undefined || !Number.isFinite(n)) return 'n/a';
    const sign = n > 0 ? '+' : '';
    return sign + n.toFixed(1) + '%';
  }

  function fmtAge(days) {
    if (days === null || days === undefined) return 'Unknown';
    if (days >= 365) return (days / 365).toFixed(1) + 'y';
    if (days >= 60) return Math.round(days / 30) + 'mo';
    return days + 'd';
  }

  function esc(str) {
    return String(str ?? '')
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  function clamp(x, lo, hi) {
    return Math.min(hi, Math.max(lo, x));
  }

  // Mirrors lib/model.ts scoreProtocol so the Model Sandbox recalculates live with identical math.
  function computeImpliedValue(row, overrides) {
    const cfg = DATA.model;
    const growthWeight = overrides.growth_weight;
    const maturityRange = overrides.maturity_range;
    const chainBonus = overrides.chain_bonus_per_extra;
    const scaleExp = overrides.scale_exponent;

    const catMult = row.model.category_multiple;
    const gClamped = clamp(row.change_7d ?? 0, cfg.growth_floor_pct, cfg.growth_cap_pct);
    const gMult = 1 + (gClamped / 100) * growthWeight;
    const effAge = row.age_days ?? cfg.unknown_age_days;
    const mMult = cfg.maturity_floor + (clamp(effAge, 0, cfg.maturity_days) / cfg.maturity_days) * maturityRange;
    const extraChains = Math.min(Math.max((row.chains.length || 1) - 1, 0), cfg.chain_bonus_max_extra);
    const cMult = 1 + extraChains * chainBonus;
    const sMult = clamp((Math.max(row.tvl_usd, 1) / cfg.scale_anchor_usd) ** scaleExp, cfg.scale_floor, cfg.scale_cap);

    const composite = catMult * gMult * mMult * cMult * sMult;
    return {
      implied: Math.max(1, Math.round(row.tvl_usd * composite)),
      composite,
      gMult,
      mMult,
      cMult,
      sMult,
    };
  }

  // Parse optional URL search params for deterministic view inspection (fully offline).
  function applyUrlState() {
    const sp = new URLSearchParams(window.location.search);
    if (sp.has('view') && ['board', 'live', 'calibration', 'sandbox'].includes(sp.get('view'))) {
      state.view = sp.get('view');
    }
    if (sp.has('tier') && ['all', 'watchlist', 'early'].includes(sp.get('tier'))) {
      state.tier = sp.get('tier');
    }
    if (sp.has('category')) state.category = sp.get('category');
    if (sp.has('chain')) state.chain = sp.get('chain');
    if (sp.has('risk')) state.risk = sp.get('risk');
    if (sp.has('q')) state.query = sp.get('q');
    if (sp.has('sort')) state.sortKey = sp.get('sort');
    if (sp.has('dir') && (sp.get('dir') === 'asc' || sp.get('dir') === 'desc')) {
      state.sortDir = sp.get('dir');
    }
    if (sp.has('detail')) state.selectedSlug = sp.get('detail');
  }

  // Precompute category and chain option lists with counts.
  const categoryCounts = new Map();
  const chainCounts = new Map();
  for (const r of DATA.rows) {
    const cat = r.category || 'Uncategorized';
    categoryCounts.set(cat, (categoryCounts.get(cat) || 0) + 1);
    for (const ch of r.chains) {
      chainCounts.set(ch, (chainCounts.get(ch) || 0) + 1);
    }
  }
  const sortedCategories = [...categoryCounts.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
  const sortedChains = [...chainCounts.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));

  function getFilteredRows() {
    const q = state.query.trim().toLowerCase();
    return DATA.rows.filter((r) => {
      if (state.tier !== 'all' && r.tier !== state.tier) return false;
      if (state.category !== 'all' && (r.category || 'Uncategorized') !== state.category) return false;
      if (state.chain !== 'all' && !r.chains.includes(state.chain)) return false;
      if (state.risk !== 'all' && r.farm.risk_tier !== state.risk) return false;
      if (q) {
        const hay = `${r.name} ${r.slug} ${r.category || ''} ${r.chains.join(' ')}`.toLowerCase();
        if (!hay.includes(q)) return false;
      }
      return true;
    });
  }

  function sortRows(rows) {
    const dir = state.sortDir === 'asc' ? 1 : -1;
    const key = state.sortKey;
    return [...rows].sort((a, b) => {
      let va;
      let vb;
      switch (key) {
        case 'rank': va = a.rank; vb = b.rank; break;
        case 'name': return a.name.localeCompare(b.name) * dir;
        case 'tvl_usd': va = a.tvl_usd; vb = b.tvl_usd; break;
        case 'change_7d': va = a.change_7d ?? -9999; vb = b.change_7d ?? -9999; break;
        case 'age_days': va = a.age_days ?? -1; vb = b.age_days ?? -1; break;
        case 'multiple': va = a.model.composite_multiple; vb = b.model.composite_multiple; break;
        case 'implied_value_usd': va = a.implied_value_usd; vb = b.implied_value_usd; break;
        case 'readiness': va = a.model.readiness_score; vb = b.model.readiness_score; break;
        case 'capital': va = a.farm.suggested_capital_usd; vb = b.farm.suggested_capital_usd; break;
        default: va = a.rank; vb = b.rank;
      }
      if (va === vb) return a.rank - b.rank;
      return (va < vb ? -1 : 1) * dir;
    });
  }

  function hasActiveFilters() {
    return (
      state.tier !== 'all' ||
      state.category !== 'all' ||
      state.chain !== 'all' ||
      state.risk !== 'all' ||
      state.query.trim() !== ''
    );
  }

  // --- Render static header metadata, KPIs, and formula ribbon ---
  function renderMastheadMeta() {
    const pills = document.getElementById('meta-pills');
    pills.innerHTML = [
      `<span class="meta-pill">As of <strong>${esc(DATA.as_of)}</strong></span>`,
      `<span class="meta-pill">Model <strong>${esc(DATA.model.version)}</strong></span>`,
      `<span class="meta-pill">Floor <strong>${fmtUsd(DATA.floor_usd)}</strong></span>`,
      `<span class="meta-pill">Network <strong>Offline</strong></span>`,
    ].join('');
    document.getElementById('foot-source').textContent = `Snapshot date: ${DATA.as_of} · ${DATA.counts.total_protocols} protocols ingested`;
  }

  function renderKpis(filteredRows) {
    const totalImplied = DATA.rows.reduce((s, r) => s + r.implied_value_usd, 0);
    const totalTvl = DATA.rows.reduce((s, r) => s + r.tvl_usd, 0);
    const filteredImplied = filteredRows.reduce((s, r) => s + r.implied_value_usd, 0);
    const wlCount = DATA.counts.watchlist_count;
    const earlyCount = DATA.counts.early_count;
    const topRow = DATA.rows[0];

    document.getElementById('kpi-grid').innerHTML = `
      <div class="kpi-card">
        <div class="kpi-label">Total Implied Launch Value</div>
        <div class="kpi-value accent">${fmtUsd(hasActiveFilters() ? filteredImplied : totalImplied)}</div>
        <div class="kpi-sub">
          <span>${hasActiveFilters() ? `${filteredRows.length} matching rows` : `Across ${DATA.rows.length} pre-token rows`}</span>
          <span class="mono">TVL ${fmtUsd(hasActiveFilters() ? filteredRows.reduce((s, r) => s + r.tvl_usd, 0) : totalTvl)}</span>
        </div>
      </div>
      <div class="kpi-card">
        <div class="kpi-label">Watchlist &amp; Early Coverage</div>
        <div class="kpi-value">${wlCount}/${wlCount} <span style="font-size:13px;color:var(--pos)">100%</span></div>
        <div class="kpi-sub">
          <span>${wlCount} Watchlist (&ge;$50M)</span>
          <span>+${earlyCount} Early (&lt;$50M)</span>
        </div>
      </div>
      <div class="kpi-card">
        <div class="kpi-label">Peer-Calibrated Base Multiple</div>
        <div class="kpi-value">${DATA.calibration.global_median.toFixed(3)}x</div>
        <div class="kpi-sub">
          <span>Median mcap/TVL of ${DATA.calibration.peer_total} live peers</span>
          <span class="mono">Prior k=${DATA.model.prior_strength}</span>
        </div>
      </div>
      <div class="kpi-card">
        <div class="kpi-label">Snapshot Universe Separation</div>
        <div class="kpi-value">${DATA.counts.total_protocols}</div>
        <div class="kpi-sub">
          <span>${DATA.counts.live_token_count} live separated</span>
          <span>${DATA.counts.excluded_pre_token_count} wrapped/CEX off</span>
        </div>
      </div>
    `;
    void topRow;
  }

  function renderFormulaBand() {
    const topCats = Object.values(DATA.calibration.by_category)
      .filter((c) => c.peer_count >= 3)
      .sort((a, b) => b.peer_count - a.peer_count)
      .slice(0, 6);

    const chips = topCats
      .map((c) => `<span class="peer-chip">${esc(c.category)} <b>${c.shrunk_multiple.toFixed(2)}x</b> (n=${c.peer_count})</span>`)
      .join('');

    document.getElementById('formula-band').innerHTML = `
      <div class="formula-eq">
        <span class="formula-tag">Valuation Model</span>
        <span class="formula-code">Implied = TVL &times; CatMult<sub>Bayes</sub> &times; Growth<sub>7d</sub> &times; Maturity<sub>age</sub> &times; Chains &times; Scale</span>
      </div>
      <div class="peer-chips">${chips}</div>
    `;
  }

  function renderToolbar(filteredRows) {
    const tb = document.getElementById('toolbar');
    const af = document.getElementById('active-filters');
    if (state.view !== 'board') {
      tb.hidden = true;
      af.hidden = true;
      return;
    }
    tb.hidden = false;

    const catOpts = ['<option value="all">All Categories</option>']
      .concat(sortedCategories.map(([c, n]) => `<option value="${esc(c)}"${state.category === c ? ' selected' : ''}>${esc(c)} (${n})</option>`))
      .join('');
    const chainOpts = ['<option value="all">All Chains</option>']
      .concat(sortedChains.map(([c, n]) => `<option value="${esc(c)}"${state.chain === c ? ' selected' : ''}>${esc(c)} (${n})</option>`))
      .join('');
    const riskOpts = ['all', 'Moderate', 'Elevated', 'High']
      .map((rk) => `<option value="${rk}"${state.risk === rk ? ' selected' : ''}>${rk === 'all' ? 'All Risk Tiers' : rk + ' Risk'}</option>`)
      .join('');

    tb.innerHTML = `
      <div class="tier-group" role="group" aria-label="Tier filter">
        <button type="button" class="tier-btn${state.tier === 'all' ? ' active' : ''}" data-tier="all">All (${DATA.rows.length})</button>
        <button type="button" class="tier-btn${state.tier === 'watchlist' ? ' active' : ''}" data-tier="watchlist">Watchlist (${DATA.counts.watchlist_count})</button>
        <button type="button" class="tier-btn${state.tier === 'early' ? ' active' : ''}" data-tier="early">Early &lt;$50M (${DATA.counts.early_count})</button>
      </div>
      <input type="search" id="search-input" class="ctrl-input" placeholder="Search protocol, category, or chain..." value="${esc(state.query)}">
      <select id="cat-select" class="ctrl-select" aria-label="Category filter">${catOpts}</select>
      <select id="chain-select" class="ctrl-select" aria-label="Chain filter">${chainOpts}</select>
      <select id="risk-select" class="ctrl-select" aria-label="Risk tier filter">${riskOpts}</select>
      <button type="button" class="btn-ghost" id="reset-btn">Reset</button>
    `;

    tb.querySelectorAll('.tier-btn').forEach((btn) => {
      btn.addEventListener('click', () => {
        state.tier = btn.dataset.tier;
        state.page = 1;
        render();
      });
    });

    const searchInput = document.getElementById('search-input');
    searchInput.addEventListener('input', (e) => {
      state.query = e.target.value;
      state.page = 1;
      renderBodyAndKpis();
    });

    document.getElementById('cat-select').addEventListener('change', (e) => {
      state.category = e.target.value;
      state.page = 1;
      render();
    });
    document.getElementById('chain-select').addEventListener('change', (e) => {
      state.chain = e.target.value;
      state.page = 1;
      render();
    });
    document.getElementById('risk-select').addEventListener('change', (e) => {
      state.risk = e.target.value;
      state.page = 1;
      render();
    });
    document.getElementById('reset-btn').addEventListener('click', () => {
      state.tier = 'all';
      state.category = 'all';
      state.chain = 'all';
      state.risk = 'all';
      state.query = '';
      state.sortKey = 'rank';
      state.sortDir = 'asc';
      state.page = 1;
      render();
    });

    renderActiveFilterBar(filteredRows);
  }

  function renderActiveFilterBar(filteredRows) {
    const af = document.getElementById('active-filters');
    if (state.view !== 'board' || !hasActiveFilters()) {
      af.hidden = true;
      return;
    }
    af.hidden = false;
    const tags = [];
    if (state.tier !== 'all') tags.push(`Tier: ${state.tier === 'watchlist' ? 'Watchlist >=$50M' : 'Early <$50M'}`);
    if (state.category !== 'all') tags.push(`Category: ${state.category}`);
    if (state.chain !== 'all') tags.push(`Chain: ${state.chain}`);
    if (state.risk !== 'all') tags.push(`Risk: ${state.risk}`);
    if (state.query.trim()) tags.push(`Search: "${state.query.trim()}"`);

    const sumTvl = filteredRows.reduce((s, r) => s + r.tvl_usd, 0);
    const sumImp = filteredRows.reduce((s, r) => s + r.implied_value_usd, 0);

    af.innerHTML = `
      <div class="filter-tags">
        <span>Active filters:</span>
        ${tags.map((t) => `<span class="filter-tag">${esc(t)}</span>`).join('')}
      </div>
      <div class="mono">${filteredRows.length} protocols · TVL ${fmtUsd(sumTvl)} · Implied ${fmtUsd(sumImp)}</div>
    `;
  }

  function sortIndicator(key) {
    if (state.sortKey !== key) return '';
    return state.sortDir === 'asc' ? ' ▲' : ' ▼';
  }

  function renderBoardTable(filteredRows) {
    const sorted = sortRows(filteredRows);
    const totalPages = Math.max(1, Math.ceil(sorted.length / state.pageSize));
    if (state.page > totalPages) state.page = totalPages;
    const start = (state.page - 1) * state.pageSize;
    const slice = sorted.slice(start, start + state.pageSize);
    const compact = Boolean(state.selectedSlug);

    const container = document.getElementById('view-container');
    if (slice.length === 0) {
      container.innerHTML = '<div class="empty-state">No pre-token protocols match the current filters. Click Reset to view all 178 rows.</div>';
      document.getElementById('pager').innerHTML = '';
      return;
    }

    const cols = [
      { key: 'rank', label: 'Rank', num: false },
      { key: 'name', label: 'Protocol', num: false },
      { key: 'implied_value_usd', label: 'Implied Value', num: true },
      { key: 'tvl_usd', label: 'TVL', num: true },
      { key: 'multiple', label: 'Mult', num: true },
      { key: 'change_7d', label: '7d TVL', num: true },
      ...(compact ? [] : [
        { key: 'age_days', label: 'Age', num: true },
        { key: null, label: 'Chains', num: false },
        { key: 'readiness', label: 'Readiness', num: true },
        { key: 'capital', label: 'Farm Plan', num: false },
      ]),
    ];

    const thead = cols
      .map((c) => {
        const cls = [c.num ? 'num' : '', c.key ? 'sortable' : '', state.sortKey === c.key ? 'sorted' : ''].filter(Boolean).join(' ');
        const attr = c.key ? ` data-sort="${c.key}"` : '';
        return `<th class="${cls}"${attr}>${c.label}${c.key ? sortIndicator(c.key) : ''}</th>`;
      })
      .join('');

    const tbody = slice
      .map((r) => {
        const chgCls = r.change_7d === null ? 'chg-flat' : r.change_7d >= 0 ? 'chg-pos' : 'chg-neg';
        const tierBadge = r.tier === 'watchlist'
          ? '<span class="badge badge-wl">Watchlist</span>'
          : '<span class="badge badge-early">Early</span>';
        const chainPills = r.chains.slice(0, 2).map((c) => `<span class="chain-pill">${esc(c)}</span>`).join('') +
          (r.chains.length > 2 ? `<span class="chain-pill">+${r.chains.length - 2}</span>` : '');
        const isSel = state.selectedSlug === r.slug;

        return `
          <tr data-slug="${esc(r.slug)}" class="${isSel ? 'selected' : ''}">
            <td class="rank-cell">#${r.rank}</td>
            <td class="proto-cell">
              <div class="proto-name">${esc(r.name)} ${tierBadge}</div>
              <div class="proto-sub">${esc(r.category || 'Uncategorized')}</div>
            </td>
            <td class="num val-strong">${fmtUsd(r.implied_value_usd)}</td>
            <td class="num mono">${fmtUsd(r.tvl_usd)}</td>
            <td class="num mono">${r.model.composite_multiple.toFixed(2)}x</td>
            <td class="num ${chgCls}">${fmtPct(r.change_7d)}</td>
            ${compact ? '' : `
              <td class="num mono">${fmtAge(r.age_days)}</td>
              <td><div class="chains-wrap">${chainPills}</div></td>
              <td class="num">
                <div class="readiness-bar">
                  <span class="bar-track"><span class="bar-fill" style="width:${r.model.readiness_score}%"></span></span>
                  <span>${r.model.readiness_score}</span>
                </div>
              </td>
              <td class="farm-mini">
                <span class="mono">$${r.farm.suggested_capital_usd}</span> · ${r.farm.hold_days}d ·
                <span class="badge badge-risk-${r.farm.risk_tier}">${r.farm.risk_tier}</span>
              </td>
            `}
          </tr>
        `;
      })
      .join('');

    container.innerHTML = `<table><thead><tr>${thead}</tr></thead><tbody>${tbody}</tbody></table>`;

    container.querySelectorAll('th.sortable').forEach((th) => {
      th.addEventListener('click', () => {
        const key = th.dataset.sort;
        if (state.sortKey === key) {
          state.sortDir = state.sortDir === 'asc' ? 'desc' : 'asc';
        } else {
          state.sortKey = key;
          state.sortDir = key === 'rank' || key === 'name' ? 'asc' : 'desc';
        }
        render();
      });
    });

    container.querySelectorAll('tbody tr').forEach((tr) => {
      tr.addEventListener('click', () => {
        const slug = tr.dataset.slug;
        state.selectedSlug = state.selectedSlug === slug ? null : slug;
        render();
      });
    });

    const pager = document.getElementById('pager');
    pager.innerHTML = `
      <span>Showing <strong>${start + 1}–${start + slice.length}</strong> of <strong>${sorted.length}</strong> pre-token protocols (click any row for valuation breakdown &amp; 5-step farm plan)</span>
      <div class="pager-btns">
        <button type="button" class="btn-ghost" id="pg-prev"${state.page <= 1 ? ' disabled' : ''}>Prev</button>
        <span class="mono">Page ${state.page} / ${totalPages}</span>
        <button type="button" class="btn-ghost" id="pg-next"${state.page >= totalPages ? ' disabled' : ''}>Next</button>
      </div>
    `;
    document.getElementById('pg-prev').addEventListener('click', () => {
      if (state.page > 1) { state.page -= 1; render(); }
    });
    document.getElementById('pg-next').addEventListener('click', () => {
      if (state.page < totalPages) { state.page += 1; render(); }
    });
  }

  function renderLiveBenchmarks() {
    const container = document.getElementById('view-container');
    document.getElementById('pager').innerHTML = `<span>Showing top ${DATA.live.length} live-token DeFi protocols by market cap — strictly separated from the pre-token launch board.</span>`;

    const rows = DATA.live
      .map((p, idx) => {
        const chgCls = p.change_7d === null ? 'chg-flat' : p.change_7d >= 0 ? 'chg-pos' : 'chg-neg';
        const chainPills = p.chains.slice(0, 3).map((c) => `<span class="chain-pill">${esc(c)}</span>`).join('');
        return `
          <tr style="cursor:default">
            <td class="rank-cell">${idx + 1}</td>
            <td class="proto-cell">
              <div class="proto-name">${esc(p.name)} <span class="badge badge-live">${esc(p.symbol || 'LIVE')}</span></div>
              <div class="proto-sub">${esc(p.category || 'Uncategorized')}</div>
            </td>
            <td class="num val-strong">${fmtUsd(p.mcap_usd)}</td>
            <td class="num mono">${fmtUsd(p.tvl_usd)}</td>
            <td class="num mono">${p.mcap_tvl_ratio.toFixed(2)}x</td>
            <td class="num ${chgCls}">${fmtPct(p.change_7d)}</td>
            <td><div class="chains-wrap">${chainPills}</div></td>
          </tr>
        `;
      })
      .join('');

    container.innerHTML = `
      <table>
        <thead>
          <tr>
            <th>#</th>
            <th>Live Protocol</th>
            <th class="num">Market Cap</th>
            <th class="num">TVL</th>
            <th class="num">MCap / TVL</th>
            <th class="num">7d TVL</th>
            <th>Chains</th>
          </tr>
        </thead>
        <tbody>${rows}</tbody>
      </table>
    `;
  }

  function renderCalibrationTable() {
    const container = document.getElementById('view-container');
    const items = Object.values(DATA.calibration.by_category).sort((a, b) => b.peer_count - a.peer_count || b.shrunk_multiple - a.shrunk_multiple);
    document.getElementById('pager').innerHTML = `<span>Empirical-Bayes peer calibration across ${DATA.calibration.peer_total} live non-CEX protocols. Prior shrinkage k = ${DATA.model.prior_strength} toward global median ${DATA.calibration.global_median.toFixed(4)}x.</span>`;

    const rows = items
      .map((c) => `
        <tr style="cursor:default">
          <td class="proto-name">${esc(c.category)}</td>
          <td class="num mono">${c.peer_count}</td>
          <td class="num mono">${c.p25 !== null ? c.p25.toFixed(3) + 'x' : '—'}</td>
          <td class="num mono">${c.raw_median !== null ? c.raw_median.toFixed(3) + 'x' : '—'}</td>
          <td class="num mono">${c.p75 !== null ? c.p75.toFixed(3) + 'x' : '—'}</td>
          <td class="num mono">${(c.credibility_weight * 100).toFixed(0)}%</td>
          <td class="num val-strong">${c.shrunk_multiple.toFixed(3)}x</td>
        </tr>
      `)
      .join('');

    container.innerHTML = `
      <table>
        <thead>
          <tr>
            <th>Category</th>
            <th class="num">Live Peers</th>
            <th class="num">P25 Ratio</th>
            <th class="num">Raw Median</th>
            <th class="num">P75 Ratio</th>
            <th class="num">Credibility Weight</th>
            <th class="num">Shrunk Multiple</th>
          </tr>
        </thead>
        <tbody>${rows}</tbody>
      </table>
    `;
  }

  function renderSandbox() {
    const container = document.getElementById('view-container');
    document.getElementById('pager').innerHTML = '<span>Adjust model parameters to stress-test implied valuations live using the exact same formula as lib/model.ts.</span>';

    const rescored = DATA.rows
      .map((r) => {
        const res = computeImpliedValue(r, state.sandbox);
        return { r, ...res };
      })
      .sort((a, b) => b.implied - a.implied || a.r.rank - b.r.rank);

    const rowsHtml = rescored.slice(0, 15).map((item, idx) => {
      const newRank = idx + 1;
      const deltaRank = item.r.rank - newRank;
      const deltaStr = deltaRank === 0 ? '—' : deltaRank > 0 ? `+${deltaRank}` : `${deltaRank}`;
      const deltaCls = deltaRank > 0 ? 'chg-pos' : deltaRank < 0 ? 'chg-neg' : 'chg-flat';
      const pctDiff = ((item.implied - item.r.implied_value_usd) / item.r.implied_value_usd) * 100;
      return `
        <tr data-slug="${esc(item.r.slug)}">
          <td class="rank-cell">#${newRank}</td>
          <td class="num ${deltaCls}">${deltaStr}</td>
          <td class="proto-cell"><div class="proto-name">${esc(item.r.name)}</div><div class="proto-sub">${esc(item.r.category || '')}</div></td>
          <td class="num mono">${fmtUsd(item.r.tvl_usd)}</td>
          <td class="num mono">${fmtUsd(item.r.implied_value_usd)}</td>
          <td class="num val-strong">${fmtUsd(item.implied)}</td>
          <td class="num ${pctDiff >= 0 ? 'chg-pos' : 'chg-neg'}">${fmtPct(pctDiff)}</td>
          <td class="num mono">${item.composite.toFixed(2)}x</td>
        </tr>
      `;
    }).join('');

    container.innerHTML = `
      <div class="sandbox-wrap">
        <div class="sandbox-grid">
          <div class="slider-box">
            <label><span>7d Growth Weight</span><span class="mono">${state.sandbox.growth_weight.toFixed(2)}</span></label>
            <input type="range" id="sb-growth" min="0" max="1" step="0.05" value="${state.sandbox.growth_weight}">
            <div class="slider-help">Default ${DATA.model.growth_weight} · sensitivity to 7d TVL velocity</div>
          </div>
          <div class="slider-box">
            <label><span>Maturity Range</span><span class="mono">${state.sandbox.maturity_range.toFixed(2)}</span></label>
            <input type="range" id="sb-maturity" min="0" max="0.8" step="0.05" value="${state.sandbox.maturity_range}">
            <div class="slider-help">Default ${DATA.model.maturity_range} · bonus for running 3y pre-token</div>
          </div>
          <div class="slider-box">
            <label><span>Multi-Chain Bonus</span><span class="mono">+${(state.sandbox.chain_bonus_per_extra * 100).toFixed(1)}%/ch</span></label>
            <input type="range" id="sb-chain" min="0" max="0.08" step="0.005" value="${state.sandbox.chain_bonus_per_extra}">
            <div class="slider-help">Default +${(DATA.model.chain_bonus_per_extra * 100).toFixed(1)}% per extra chain (max 8)</div>
          </div>
          <div class="slider-box">
            <label><span>Scale Elasticity</span><span class="mono">${state.sandbox.scale_exponent.toFixed(2)}</span></label>
            <input type="range" id="sb-scale" min="-0.15" max="0.05" step="0.01" value="${state.sandbox.scale_exponent}">
            <div class="slider-help">Default ${DATA.model.scale_exponent} · concave TVL multiple decay</div>
          </div>
        </div>
        <table>
          <thead>
            <tr>
              <th>New Rank</th>
              <th class="num">Shift</th>
              <th>Protocol</th>
              <th class="num">TVL</th>
              <th class="num">Base Model</th>
              <th class="num">Sandbox Implied</th>
              <th class="num">Delta</th>
              <th class="num">Mult</th>
            </tr>
          </thead>
          <tbody>${rowsHtml}</tbody>
        </table>
      </div>
    `;

    const bind = (id, key) => {
      document.getElementById(id).addEventListener('input', (e) => {
        state.sandbox[key] = parseFloat(e.target.value);
        renderSandbox();
      });
    };
    bind('sb-growth', 'growth_weight');
    bind('sb-maturity', 'maturity_range');
    bind('sb-chain', 'chain_bonus_per_extra');
    bind('sb-scale', 'scale_exponent');

    container.querySelectorAll('tbody tr').forEach((tr) => {
      tr.addEventListener('click', () => {
        state.selectedSlug = tr.dataset.slug;
        renderDetail();
      });
    });
  }

  function renderDetail() {
    const ws = document.getElementById('workspace');
    const pane = document.getElementById('detail-pane');
    if (!state.selectedSlug || state.view === 'live' || state.view === 'calibration') {
      ws.classList.remove('has-detail');
      pane.hidden = true;
      return;
    }

    const row = DATA.rows.find((r) => r.slug === state.selectedSlug);
    if (!row) {
      ws.classList.remove('has-detail');
      pane.hidden = true;
      return;
    }

    ws.classList.add('has-detail');
    pane.hidden = false;
    const m = row.model;
    const f = row.farm;

    const factorBar = (label, mult, valText, isNeg) => {
      const pct = clamp((mult / 1.5) * 100, 8, 100);
      return `
        <div class="factor-row">
          <span class="factor-name">${label}</span>
          <span class="factor-bar-bg"><span class="factor-bar-fg${isNeg ? ' neg' : ''}" style="width:${pct.toFixed(0)}%"></span></span>
          <span class="factor-val">${valText}</span>
        </div>
      `;
    };

    const stepsHtml = f.steps
      .map((s) => `
        <div class="step-card">
          <div class="step-top">
            <span class="step-phase">${s.step}. ${esc(s.phase)}</span>
            <span class="step-time">${esc(s.time)}</span>
          </div>
          <p class="step-action">${esc(s.action)}</p>
          <div class="step-foot">
            <div class="step-cost"><strong>Cost:</strong> ${esc(s.cost)}</div>
            <div class="step-risk"><strong>Risk:</strong> ${esc(s.risk)}</div>
          </div>
        </div>
      `)
      .join('');

    pane.innerHTML = `
      <div class="detail-head">
        <div>
          <div>
            <span class="badge ${row.tier === 'watchlist' ? 'badge-wl' : 'badge-early'}">${row.tier === 'watchlist' ? 'Watchlist' : 'Early Radar'}</span>
            <span class="meta-pill" style="margin-left:4px">Rank #${row.rank}</span>
          </div>
          <h2 class="detail-title">${esc(row.name)}</h2>
          <div class="detail-sub">${esc(row.category || 'Uncategorized')} · ${row.chains.length} chain${row.chains.length === 1 ? '' : 's'} (${esc(row.chains.slice(0, 4).join(', '))}${row.chains.length > 4 ? '…' : ''})</div>
        </div>
        <button type="button" class="close-btn" id="close-detail" aria-label="Close detail">&times;</button>
      </div>

      <div class="detail-hero">
        <div class="hero-box primary">
          <div class="hero-k">Implied Value</div>
          <div class="hero-v">${fmtUsd(row.implied_value_usd)}</div>
          <div class="hero-note">${m.composite_multiple.toFixed(3)}x TVL</div>
        </div>
        <div class="hero-box">
          <div class="hero-k">Current TVL</div>
          <div class="hero-v">${fmtUsd(row.tvl_usd)}</div>
          <div class="hero-note">7d: ${fmtPct(row.change_7d)}</div>
        </div>
        <div class="hero-box">
          <div class="hero-k">Readiness</div>
          <div class="hero-v">${m.readiness_score}/100</div>
          <div class="hero-note">Age: ${fmtAge(row.age_days)}</div>
        </div>
      </div>

      <div class="section-h">
        <span>Valuation Factor Breakdown</span>
        <span class="mono">Base ${fmtUsd(m.base_value_usd)}</span>
      </div>
      <div class="factor-list">
        ${factorBar(`Category (${m.category_peer_count} peers)`, m.category_multiple * 2.5, `${m.category_multiple.toFixed(3)}x`, false)}
        ${factorBar(`7d Momentum (${fmtPct(row.change_7d)})`, m.growth_multiplier, `${m.growth_multiplier.toFixed(3)}x`, m.growth_multiplier < 1)}
        ${factorBar(`Age Maturity (${fmtAge(row.age_days)})`, m.maturity_multiplier, `${m.maturity_multiplier.toFixed(3)}x`, m.maturity_multiplier < 0.85)}
        ${factorBar(`Multi-Chain (${m.chain_count} ch)`, m.multichain_multiplier, `${m.multichain_multiplier.toFixed(3)}x`, false)}
        ${factorBar('Scale Elasticity', m.scale_multiplier, `${m.scale_multiplier.toFixed(3)}x`, m.scale_multiplier < 0.95)}
      </div>
      <div class="band-box">
        <span>Bear ${fmtUsd(m.low_value_usd)}</span>
        <strong>Base ${fmtUsd(row.implied_value_usd)}</strong>
        <span>Bull ${fmtUsd(m.high_value_usd)}</span>
      </div>

      <div class="section-h">
        <span>Concrete Farm Playbook</span>
        <span class="badge badge-risk-${f.risk_tier}">${f.risk_tier} Risk</span>
      </div>
      <div class="farm-meta">
        <div class="farm-stat"><span>Primary Chain</span><b>${esc(f.primary_chain)}</b></div>
        <div class="farm-stat"><span>Capital</span><b>$${f.suggested_capital_usd}</b></div>
        <div class="farm-stat"><span>Est. Gas</span><b>~$${f.estimated_gas_usd < 1 ? f.estimated_gas_usd.toFixed(2) : Math.round(f.estimated_gas_usd)}</b></div>
        <div class="farm-stat"><span>Hold Window</span><b>${f.hold_days} days</b></div>
      </div>
      <div class="step-list">${stepsHtml}</div>
    `;

    document.getElementById('close-detail').addEventListener('click', () => {
      state.selectedSlug = null;
      render();
    });
  }

  function renderBodyAndKpis() {
    const filtered = getFilteredRows();
    renderKpis(filtered);
    renderActiveFilterBar(filtered);
    if (state.view === 'board') renderBoardTable(filtered);
    else if (state.view === 'live') renderLiveBenchmarks();
    else if (state.view === 'calibration') renderCalibrationTable();
    else renderSandbox();
    renderDetail();
  }

  function render() {
    document.querySelectorAll('.tab-btn').forEach((b) => {
      b.classList.toggle('active', b.dataset.view === state.view);
    });
    const filtered = getFilteredRows();
    renderToolbar(filtered);
    renderBodyAndKpis();
  }

  document.querySelectorAll('.tab-btn').forEach((btn) => {
    btn.addEventListener('click', () => {
      state.view = btn.dataset.view;
      render();
    });
  });

  applyUrlState();
  renderMastheadMeta();
  renderFormulaBand();
  render();
})();
